<?php
require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/helpers.php';$pageTitle='Reportes estratégicos';
try{$demanda=oracle_cursor('AV_JP_RM_BE_SP_REPORTE_DEMANDA_JUEGO');$ranking=oracle_cursor('AV_JP_RM_BE_SP_REPORTE_RANKING_MVP');$ocupacion=oracle_cursor('AV_JP_RM_BE_SP_REPORTE_OCUPACION_SEDES');}catch(Throwable $e){$error=$e->getMessage();$demanda=$ranking=$ocupacion=[];}
include __DIR__.'/includes/header.php';?>
<main class="content"><div class="page-head"><div><h1>📊 Reportes estratégicos</h1><p>Los tres dashboards definidos en la propuesta, alimentados por procedimientos Oracle.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><div class="grid grid-3"><section class="panel"><h2 class="section-title">1. Demanda y recaudación</h2><div class="table-wrap"><table><thead><tr><th>Videojuego</th><th>Torneos</th><th>Equipos</th><th>Recaudación</th></tr></thead><tbody><?php foreach($demanda as $r):?><tr><td><?=h($r['VIDEOJUEGO'])?></td><td><?=h($r['TORNEOS'])?></td><td><?=h($r['EQUIPOS_INSCRITOS'])?></td><td><?=money($r['RECAUDACION'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2 class="section-title">2. Ranking MVP</h2><div class="table-wrap"><table><thead><tr><th>Jugador</th><th>KDA</th><th>MVP</th><th>Victorias</th></tr></thead><tbody><?php foreach($ranking as $r):?><tr><td><?=h($r['NICKNAME'])?></td><td><strong><?=h($r['RATIO_KDA'])?></strong><div class="mini-note"><?=h($r['KILLS'].'/'.$r['DEATHS'].'/'.$r['ASSISTS'])?></div></td><td><?=h($r['VECES_MVP'])?></td><td><?=h($r['VICTORIAS'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2 class="section-title">3. Ocupación y balance</h2><div class="table-wrap"><table><thead><tr><th>Torneo</th><th>Sede</th><th>Ocupación</th><th>Balance</th></tr></thead><tbody><?php foreach($ocupacion as $r):$pct=min(100,max(0,(float)$r['OCUPACION_PORCENTAJE']));?><tr><td><?=h($r['TORNEO'])?></td><td><?=h($r['SEDE'])?></td><td><?=h($r['INSCRITOS'].'/'.$r['CUPO_MAXIMO'])?><div class="bar"><span style="width:<?=$pct?>%"></span></div><div class="mini-note"><?=h($r['OCUPACION_PORCENTAJE'])?>%</div></td><td><?=money($r['BALANCE_ESTIMADO'])?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include __DIR__.'/includes/footer.php';?>
